  [[ -f $POSITIONS ]] || print -r -- $'position\tconfig\tprotocol\tmeasure_exit\tcache_check\tlogged_at_utc' > $POSITIONS
  print -r -- "$n"$'\t'"$config"$'\t'"${${proto:t:r}#protocol-}"$'\t'"$rc"$'\t'"$result"$'\t'"$(date -u +%Y-%m-%dT%H:%M:%SZ)" >> $POSITIONS
