# ps etime, [[dd-]hh:]mm:ss, in seconds.
_etime_seconds() {
  local t=$1 d=0 h=0 m=0 s=0
  local -a parts
  if [[ $t == *-* ]]; then d=${t%%-*}; t=${t#*-}; fi
  parts=(${(s.:.)t})
